IF Drive_Auto THEN 
        Drive_OP  := Drive_M_OP;
    ELSE
	Drive_OP  := Drive_Auto_OP;
	Drive_M_OP:= Drive_Auto_OP;
END_IF;

IF Drive_Auto THEN 
        Drive_OP  := Drive_M_OP;
	Drive_CL  := NOT Drive_M_OP;
    ELSE
	Drive_OP  := Drive_Auto_OP;

	Drive_CL  := NOT Drive_Auto_OP;
