END_IF;

IF (EU_Max - EU_Min) <> 0.0 THEN
    AO_Real := (PV_Real - EU_Min) * (Raw_High - Raw_Low) / (EU_Max - EU_Min) + Raw_Low;
ELSE
    AO_Real := 0.0;
END_IF;

IF AO_Real > Raw_High THEN AO_Real := Raw_High; END_IF;
IF AO_Real < Raw_Low  THEN AO_Real := Raw_Low;  END_IF;

AO_Raw := REAL_TO_INT (IN := AO_Real);

attribute.value:
