The number of inputs can be increased.
Formula OUT = MAX {IN1, IN2, .., INn}

FBProgram.STSource:
(*=====================================================
   Function: analog scaling + 4-level alarms + alarm delay + hysteresis + hold on wire break
   For: Schneider M340/M580
   Platform: EcoStruxure
   Language: ST
   Zhao Jianchun  jianchun.zhao@jci.com
======================================================*)
(* 1. Range calculation *)
    RawRange_INT  :=  RawMax-RawMin;
    RawRange      :=  INT_TO_REAL(IN := RawRange_INT);
    ScaleRange    := ScaleMax - ScaleMin;
    UnderRange    := AI_Raw < (RawMin - 400);
    OverRange     := AI_Raw > (RawMax + 400);

(* 2. Engineering scaling + hold on wire break *)
IF NOT UnderRange AND NOT OverRange THEN
    RawDelta_Int := AI_Raw - RawMin;
    RawDelta := INT_TO_REAL(IN := RawDelta_Int);
    AI_PV    := ScaleMin + (RawDelta / RawRange) * ScaleRange;
    LastValue:= AI_PV;
ELSE
    AI_PV    := LastValue; 
END_IF;

(* Low-low alarm *)
  IF (Not LL_Pre) And AI_PV < Alarm_LL_Value THEN 
    LL_Pre:= true;
  END_IF;
  IF LL_Pre And AI_PV > (Alarm_LL_Value + SP_Hyst)  THEN 
    LL_Pre:= false;
  END_IF;
(* Low-low alarm *)
  IF (Not L_Pre) And AI_PV < Alarm_L_Value THEN 
    L_Pre:= true;
   END_IF;
   IF L_Pre And AI_PV > (Alarm_L_Value + SP_Hyst)  THEN 
    L_Pre:= false;
   END_IF;
(* High alarm *)
   IF (Not H_Pre) And AI_PV > Alarm_H_Value THEN 
    H_Pre:= true;
   END_IF;
   IF H_Pre And AI_PV < (Alarm_H_Value - SP_Hyst)  THEN 
    H_Pre:= false;
   END_IF;
(* High-high alarm *)
  IF (Not HH_Pre) And AI_PV > Alarm_HH_Value THEN 
    HH_Pre:= true;
   END_IF;
  IF HH_Pre And AI_PV < (Alarm_HH_Value - SP_Hyst)  THEN 
    HH_Pre:= false;
  END_IF;

IF NOT Alarm_Enable then
   LL_Pre:= false;
    L_Pre:= false;
    H_Pre:= false;
   HH_Pre:= false;
END_IF;
(* Alarm delay output *)

Alarm_Delay_Time:=DINT_TO_Time(Alarm_Delay_SP *1000); 


LL_Timer (IN := LL_Pre,
       	  PT := Alarm_Delay_Time,
          Q  => Alarm_LL);

L_Timer  (IN := L_Pre,
       	  PT := Alarm_Delay_Time,
          Q  => Alarm_L);

H_Timer  (IN := H_Pre,
       	  PT := Alarm_Delay_Time,
          Q  => Alarm_H);

HH_Timer  (IN := HH_Pre,
       	  PT := Alarm_Delay_Time,
          Q  => Alarm_HH);

