IF Condition THEN
    IF Condition_Delay < SP_Condition_Delay AND SEC_P THEN
        Condition_Delay := Condition_Delay + 1;
    END_IF;
    IF Condition_Delay >= SP_Condition_Delay THEN
        Condition_OK := true;
    ELSE
        Condition_OK := false;
    END_IF;
ELSE
    Condition_Delay := 0;
    Condition_OK := false;
END_IF;

