(* 2026-10-15 bench test (user): line 2 data from READ_VAR (Main FBD, SMCL 10.54.18.134 %MW200) *)
RX2_HB := RX2_BLK[0];
RX2_BITS := RX2_BLK[1];
RX2_SPD := RX2_BLK[2];
RX2_TSP := RX2_BLK[3];
RX2_CHWST := RX2_BLK[4];
RX2_OAT := RX2_BLK[5];
RX2_PRIM := RX2_BLK[6];

(* Receive the SMCL commands. line 1 %MW600..619 (10.54.18.134), line 2 %MW620..639 (10.54.18.135), read by NOE IO Scanning.
   Heartbeat unchanged for COMM_TMO s = comm lost; with both lines lost keep the last enable, speed and setpoint (SOO: hold pump speed). *)
IF RX1_HB <> RX1_HB_LAST THEN
    RX1_HB_LAST := RX1_HB; RX1_CNT := 0;
ELSIF SEC_P AND (RX1_CNT < 30000) THEN
    RX1_CNT := RX1_CNT + 1;
END_IF;
IF RX2_HB <> RX2_HB_LAST THEN
    RX2_HB_LAST := RX2_HB; RX2_CNT := 0;
ELSIF SEC_P AND (RX2_CNT < 30000) THEN
    RX2_CNT := RX2_CNT + 1;
END_IF;
Network_Main := RX1_CNT < COMM_TMO;
Network_Stby := RX2_CNT < COMM_TMO;

SMCL_COMM_OK := TRUE;
IF Network_Main AND ((RX1_BITS AND 16#0020) <> 0) THEN
    RX_BITS := RX1_BITS; RX_SPD := RX1_SPD; RX_TSP := RX1_TSP; RX_CHWST := RX1_CHWST; RX_OAT := RX1_OAT;
ELSIF Network_Stby AND ((RX2_BITS AND 16#0020) <> 0) THEN
    RX_BITS := RX2_BITS; RX_SPD := RX2_SPD; RX_TSP := RX2_TSP; RX_CHWST := RX2_CHWST; RX_OAT := RX2_OAT;
ELSE
    SMCL_COMM_OK := FALSE;
END_IF;
(* 2026-10-19: b5 = SMCL command block valid. The SMCL clears it after a restart until it has the stage back
   (cold start after both CPUs lost power) -> handled like comm lost: keep the last enable, speed and setpoint *)
IF (RX_BITS AND 16#0020) = 0 THEN
    SMCL_COMM_OK := FALSE;
END_IF;
ALM_SMCL_COMM := NOT SMCL_COMM_OK AND NOT LOCAL_EN;

SMCL_RESET := FALSE;
IF LOCAL_EN THEN
    (* Local mode: use the LOCAL_ variables directly *)
    ACH_EN := LOCAL_ACH_EN;
    CHVSD_SEQ_OUT := LOCAL_SPD;
    CHS_TSP_OUT := LOCAL_TSP;
    CHS := TRUE;
    Other_Chemical_Mode_Runing := FALSE;
    SMCL_RESET := FALSE;
ELSIF SMCL_COMM_OK THEN
    ACH_EN := (RX_BITS AND 16#0001) <> 0;
    Other_Chemical_Mode_Runing := (RX_BITS AND 16#0002) <> 0;
    CHS := (RX_BITS AND 16#0004) <> 0;
    SMCL_RESET_TRIG (CLK := (RX_BITS AND 16#0008) <> 0);
    SMCL_RESET := SMCL_RESET_TRIG.Q;
    CH_LEAD := (RX_BITS AND 16#0010) <> 0;
    CHVSD_SEQ_OUT := LIMIT(0.0, INT_TO_REAL(RX_SPD) / 100.0, 100.0);
    IF RX_TSP > 0 THEN
        CHS_TSP_OUT := INT_TO_REAL(RX_TSP) / 100.0;
    END_IF;
    CHWS_T01_T02 := INT_TO_REAL(RX_CHWST) / 100.0;
    OA_T := INT_TO_REAL(RX_OAT) / 100.0;
END_IF;

(* 2026-10-20 user (ACH-01 edit): control supply temperature from the unit's own CHS-T01 / CHS-T02 when valid *)
CHWS_T_OK := (NOT (CHS_T01_UnderRange OR CHS_T01_OverRange)) OR (NOT (CHS_T02_UnderRange OR CHS_T02_OverRange));
IF (NOT (CHS_T01_UnderRange OR CHS_T01_OverRange)) AND (NOT (CHS_T02_UnderRange OR CHS_T02_OverRange)) THEN
    CHWS_T01_T02 := MAX(CHS_T01, CHS_T02);
ELSIF (NOT (CHS_T01_UnderRange OR CHS_T01_OverRange)) THEN
    CHWS_T01_T02 := CHS_T01;
ELSIF (NOT (CHS_T02_UnderRange OR CHS_T02_OverRange)) THEN
    CHWS_T01_T02 := CHS_T02;
END_IF;

P06_ChemGrant := SMCL_COMM_OK AND NOT LOCAL_EN AND ((RX_BITS AND 16#0040) <> 0);

(* Modbus RTU master (CPU serial port, single bus, BMS-S01-03-01)
   Address 5 VSD IVS102: read 100..110, 300 (table 03)
   Address 6 pump power meter iEM3000: read 3000..3077, Float32 high word first (table 04)
   Address 7 chiller YVAM1500: read 1..29, 61..72, 65001; write 1 = supply setpoint x10 (table 05; the only way to set the chiller, AO no longer used)
   Address 8 storage tank, address 9 tank heat tracing: register tables pending, not polled yet
   One request at a time; process the result before sending the next. RTU_ERR_MAX failures in a row = comm fault.
   Note: set the CPU serial port to Modbus master in the hardware configuration; baud rate/parity per device. *)
RTU_ADR_VFD := ADDM('0.0.0.5');
RTU_ADR_PPM := ADDM('0.0.0.6');
RTU_ADR_ACH := ADDM('0.0.0.7');
RTU_BUSY := (RTU_GEST[0] AND 16#0001) <> 0;

IF SIM_EN OR NOT RTU_EN THEN
    RTU_STEP := 1; RTU_SENT := FALSE;
    ERR_VFD := 0; ERR_PPM := 0; ERR_ACH := 0;
ELSIF NOT RTU_BUSY THEN
    IF RTU_SENT THEN
        (* ---------- process the result of the previous request ---------- *)
        RTU_SENT := FALSE;
        RTU_OK := RTU_GEST[1] = 0;
        CASE RTU_STEP OF
        1:  (* VSD 100..110 *)
            IF RTU_OK THEN
                FOR I := 0 TO 10 DO VFD_RAW[I] := RTU_BUF[I]; END_FOR;
                VFD_SPD_RPM := RTU_BUF[0];
                VFD_SPD_RAW := RTU_BUF[1];
            END_IF;
        2:  (* VSD 300 *)
            IF RTU_OK THEN VFD_CTRL_MODE := RTU_BUF[0]; END_IF;
        3:  (* meter 3000..3077: array index = register - 3000 *)
            IF RTU_OK THEN
                (* Registers 3010 current avg, 3026 line voltage avg, 3060 active, 3068 reactive, 3076 apparent *)
                PPM_IDX[0] := 10; PPM_IDX[1] := 26; PPM_IDX[2] := 60; PPM_IDX[3] := 68; PPM_IDX[4] := 76;
                FOR I := 0 TO 4 DO
                    (* Float32 high word first, decoded per IEEE754 (M340 has no located %MF variables) *)
                    FLT_HI := INT_TO_DINT(RTU_BUF[PPM_IDX[I]]);
                    IF FLT_HI < 0 THEN FLT_HI := FLT_HI + 65536; END_IF;
                    FLT_LO := INT_TO_DINT(RTU_BUF[PPM_IDX[I] + 1]);
                    IF FLT_LO < 0 THEN FLT_LO := FLT_LO + 65536; END_IF;
                    FLT_E := DINT_TO_INT((FLT_HI / 128) MOD 256);
                    FLT_M := (FLT_HI MOD 128) * 65536 + FLT_LO;
                    IF (FLT_E = 0) OR (FLT_E = 255) THEN      (* 0, denormal, NaN/inf treated as 0 *)
                        PPM_VAL[I] := 0.0;
                    ELSE
                        PPM_VAL[I] := (1.0 + DINT_TO_REAL(FLT_M) / 8388608.0) * EXP(INT_TO_REAL(FLT_E - 127) * 0.69314718);
                        IF FLT_HI >= 32768 THEN PPM_VAL[I] := -PPM_VAL[I]; END_IF;
                    END_IF;
                END_FOR;
                PPM_I_AVG := PPM_VAL[0]; PPM_U_LL := PPM_VAL[1]; PPM_KW := PPM_VAL[2];
                PPM_KVAR := PPM_VAL[3]; PPM_KVA := PPM_VAL[4];
            END_IF;
        4:  (* chiller 1..29: index = register - 1 *)
            IF RTU_OK THEN
                ACH_SP_RB := INT_TO_REAL(RTU_BUF[0]) / 10.0;
                LCHLT := INT_TO_REAL(RTU_BUF[4]) / 10.0;
                ECHLT := INT_TO_REAL(RTU_BUF[5]) / 10.0;
                ACH_OAT := INT_TO_REAL(RTU_BUF[15]) / 10.0;
                ACH_ACT_SP := INT_TO_REAL(RTU_BUF[19]) / 10.0;
                ACH_OPH := INT_TO_DINT(RTU_BUF[25]);
                IF ACH_OPH < 0 THEN ACH_OPH := ACH_OPH + 65536; END_IF;
                ACH_FLA := INT_TO_REAL(RTU_BUF[28]) / 10.0;
                IF ACH_UNITS = 0 THEN          (* imperial °F -> °C *)
                    ACH_SP_RB := (ACH_SP_RB - 32.0) / 1.8;
                    LCHLT := (LCHLT - 32.0) / 1.8;
                    ECHLT := (ECHLT - 32.0) / 1.8;
                    ACH_OAT := (ACH_OAT - 32.0) / 1.8;
                    ACH_ACT_SP := (ACH_ACT_SP - 32.0) / 1.8;
                END_IF;
            END_IF;
        5:  (* chiller 61..72: index = register - 61 *)
            IF RTU_OK THEN
                ACH_REM_RUN_RB := RTU_BUF[0] <> 0;
                ACH_MOTOR_RUN := RTU_BUF[4] <> 0;
                (* register 66 BV6 "Chilled Liquid Pump [0=Off, 1=On]" CH LIQ PUMP STAT (05 YVAM BAS table) *)
                ACH_LIQ_PUMP := RTU_BUF[5] <> 0;
                ACH_PERMIT := RTU_BUF[7] <> 0;
                ACH_FLOWSW := RTU_BUF[8] <> 0;
                ACH_EVAP_FRZ := RTU_BUF[11] <> 0;      (* 3.2.26 evaporator freeze *)
            END_IF;
        6:  (* chiller 65001 units *)
            IF RTU_OK THEN ACH_UNITS := RTU_BUF[0]; END_IF;
        END_CASE;

        (* Comm counters *)
        IF (RTU_STEP = 1) OR (RTU_STEP = 2) THEN
            IF RTU_OK THEN ERR_VFD := 0; ELSIF ERR_VFD < 100 THEN ERR_VFD := ERR_VFD + 1; END_IF;
        ELSIF RTU_STEP = 3 THEN
            IF RTU_OK THEN ERR_PPM := 0; ELSIF ERR_PPM < 100 THEN ERR_PPM := ERR_PPM + 1; END_IF;
        ELSE
            IF RTU_OK THEN ERR_ACH := 0; ELSIF ERR_ACH < 100 THEN ERR_ACH := ERR_ACH + 1; END_IF;
        END_IF;

        RTU_STEP := RTU_STEP + 1;
        IF RTU_STEP > 7 THEN RTU_STEP := 1; END_IF;
    ELSE
        (* ---------- send the next request ---------- *)
        IF (RTU_STEP < 1) OR (RTU_STEP > 7) THEN RTU_STEP := 1; END_IF;
        RTU_GEST[2] := RTU_TMO;
        CASE RTU_STEP OF
        1: READ_VAR(ADR := RTU_ADR_VFD, OBJ := '%MW', NUM := INT_TO_DINT(100 + RTU_OFS), NB := 11, GEST := RTU_GEST, RECP => RTU_BUF);
        2: READ_VAR(ADR := RTU_ADR_VFD, OBJ := '%MW', NUM := INT_TO_DINT(300 + RTU_OFS), NB := 1, GEST := RTU_GEST, RECP => RTU_BUF);
        3: READ_VAR(ADR := RTU_ADR_PPM, OBJ := '%MW', NUM := INT_TO_DINT(3000 + RTU_OFS), NB := 78, GEST := RTU_GEST, RECP => RTU_BUF);
        4: READ_VAR(ADR := RTU_ADR_ACH, OBJ := '%MW', NUM := INT_TO_DINT(1 + RTU_OFS), NB := 29, GEST := RTU_GEST, RECP => RTU_BUF);
        5: READ_VAR(ADR := RTU_ADR_ACH, OBJ := '%MW', NUM := INT_TO_DINT(61 + RTU_OFS), NB := 12, GEST := RTU_GEST, RECP => RTU_BUF);
        6: READ_VAR(ADR := RTU_ADR_ACH, OBJ := '%MW', NUM := 65001 + INT_TO_DINT(RTU_OFS), NB := 1, GEST := RTU_GEST, RECP => RTU_BUF);
        7: IF ACH_UNITS = 0 THEN
               RTU_WBUF[0] := REAL_TO_INT((CHS_TSP_OUT * 1.8 + 32.0) * 10.0);
           ELSE
               RTU_WBUF[0] := REAL_TO_INT(CHS_TSP_OUT * 10.0);
           END_IF;
           WRITE_VAR(ADR := RTU_ADR_ACH, OBJ := '%MW', NUM := INT_TO_DINT(1 + RTU_OFS), NB := 1, EMIS := RTU_WBUF, GEST := RTU_GEST);
        END_CASE;
        RTU_SENT := TRUE;
    END_IF;
END_IF;

COMM_VFD_FAIL := ERR_VFD >= RTU_ERR_MAX;
COMM_PPM_FAIL := ERR_PPM >= RTU_ERR_MAX;
COMM_ACH_FAIL := ERR_ACH >= RTU_ERR_MAX;

(* EVAP_PUMP (SOO FPM: pump request from the chiller) = chiller point CH LIQ PUMP STAT; OFF while the chiller link is down *)
IF RTU_EN AND NOT SIM_EN THEN
    EVAP_PUMP := ACH_LIQ_PUMP AND NOT COMM_ACH_FAIL;
ELSE
    EVAP_PUMP := FALSE;
END_IF;

(* Chiller powered: not in the chiller register table, taken from chiller controller comm OK (when PWR_FROM_COMM=TRUE) *)
IF PWR_FROM_COMM AND RTU_EN AND NOT SIM_EN THEN
    ACH_PWR_RTU := NOT COMM_ACH_FAIL;
END_IF;
(* ACH_AM_RTU (chiller remote): not in the chiller register table, kept as a software point until the vendor provides a register *)

(* When SMCL comm is lost, freeze protection uses the chiller own outdoor temperature *)
IF (NOT SMCL_COMM_OK) AND (NOT LOCAL_EN) AND (NOT COMM_ACH_FAIL) AND RTU_EN AND NOT SIM_EN THEN
    OA_T := ACH_OAT;
END_IF;

(* Input conditioning: the logic below only uses these internal variables (eases simulation) *)
IF SIM_EN THEN
    ACH_RUN := SIM_ACH_S;
    CHP_RUN := SIM_CHP_S;
    CHP_FLT_DI := SIM_CHP_F;
    CHP_REM := NOT SIM_CHP_LOCAL;
    ACH_F1 := SIM_ACH_F1;
    PHTS_RUN := PHTS_C;
    PHTS_FLT := FALSE;
    ACH_AM := NOT SIM_ACH_LOCAL;
    ACH_PWR_HW := NOT SIM_PWRLOSS;
ELSE
    ACH_RUN := ACH_S;
    CHP_RUN := CHWP_S;
    CHP_FLT_DI := CHWP_F;
    CHP_REM := CHWP_AM;
    ACH_F1 := ACH_F01;
    PHTS_RUN := PHTS_S;
    PHTS_FLT := PHTS_F;
    (* Chiller remote comes from the chiller Modbus RTU: the comm section writes software point ACH_AM_RTU (initial TRUE) *)
    ACH_AM := ACH_AM_RTU;
    (* Chiller power hardware point ACH_PW (%I0.6.5, 1 = powered; the I/O list wrongly calls it ACH_F02 chiller fault 2) *)
    ACH_PWR_HW := ACH_PW;
END_IF;

(* Chiller powered: PWR_USE_DI=TRUE uses the hardware point; FALSE uses the software point ACH_PWR_RTU
   (To judge power from chiller comm data later: write ACH_PWR_RTU in section Modbus_RTU_COMM and set PWR_USE_DI := FALSE) *)
IF PWR_USE_DI OR SIM_EN THEN
    ACH_PWR := ACH_PWR_HW;
ELSE
    ACH_PWR := ACH_PWR_RTU;
END_IF;

(* SOO: charge flow = CHS-FL01 - CHR-FL01; CHR-FL01 = I/O list AI-1 channel 1 CHWR_FL01 (named CHS_FL02 in the original program) *)
CHG_FL_RET := CHR_FL01;

(* 1 s pulse; run time (s) per SOO: unit run time counted from pump status *)
trig_1s (CLK := %S6);
SEC_P := trig_1s.Q;
IF ACH_RUN AND SEC_P THEN ACH_Runtime := ACH_Runtime + 1; END_IF;
IF CHP_RUN AND SEC_P THEN CHP_Runtime := CHP_Runtime + 1; END_IF;
IF Runtime_Reset THEN
    ACH_Runtime := 0;
    CHP_Runtime := 0;
    Runtime_Reset := FALSE;
END_IF;
CH_RUNH := CHP_Runtime / 3600;
ACH_RUNH := ACH_Runtime / 3600;

(* Test only: SIM_EN=TRUE simulates pumps, chillers, valves and flow, overriding the ANA_AI results *)
IF SIM_EN THEN
    SIM_CHP_DLY (Condition := CHP_STC AND NOT SIM_CHP_FAIL, SP_Condition_Delay := 3, SEC_P := SEC_P,
                 Condition_OK => SIM_CHP_S);
    SIM_ACH_DLY (Condition := ACH_STC AND SIM_CHP_S AND NOT SIM_ACH_FAIL AND NOT SIM_PWRLOSS,
                 SP_Condition_Delay := 20, SEC_P := SEC_P, Condition_OK => SIM_ACH_S);
    IF SEC_P THEN          (* valve moves 10% per second toward the command *)
        SIM_V1 := SIM_V1 + LIMIT(-10.0, CHV01_C - SIM_V1, 10.0);
        SIM_V2 := SIM_V2 + LIMIT(-10.0, CHV02_C - SIM_V2, 10.0);
        SIM_V3 := SIM_V3 + LIMIT(-10.0, CHV03_C - SIM_V3, 10.0);
        SIM_VB := SIM_VB + LIMIT(-10.0, CHBPV_C - SIM_VB, 10.0);
    END_IF;
    CHV01_FB := SIM_V1; CHV02_FB := SIM_V2; CHV03_FB := SIM_V3; CHBPV_FB := SIM_VB;
    IF SIM_CHP_S THEN
        CHPVSD_FB := CHPVSD_C;
        CHS_FL01 := SIM_FL_NOM * CHPVSD_C / 100.0;
    ELSE
        CHPVSD_FB := 0.0;
        CHS_FL01 := 0.0;
    END_IF;
    IF TST_MODE = 4 THEN CHR_FL01 := CHS_FL01 - SIM_CHG_FL; ELSE CHR_FL01 := CHS_FL01; END_IF;
    CHS_T01 := SIM_CHS_T; CHS_T02 := SIM_CHS_T;
    CHIN_T01 := SIM_CHIN_T; CHR_T01 := SIM_CHR_T;
    PHTS_T01 := SIM_PHTS_T; PHTS_T02 := SIM_PHTS_T; PHTS_T03 := SIM_PHTS_T; PHTS_T04 := SIM_PHTS_T;
    TST_CAP := SIM_TST_CAP;
END_IF;

(* PID external interface: PARA / MODE fields of the three PID blocks come from PID_<name>_* (SCADA writable).
   halt = PID not enabled by the sequence (OUT_ARB, previous scan) OR operator halt.
   Fix: the original Main FBD MOVE blocks wrote halt := enable, i.e. the PIDs were frozen exactly while needed. *)
(* MINFL: bypass valve minimum flow *)
CHPBV_MinFL_PID_OP_PAPR.gain := PID_MINFL_GAIN;
CHPBV_MinFL_PID_OP_PAPR.ti := DINT_TO_TIME(REAL_TO_DINT(LIMIT(0.0, PID_MINFL_TI, 100000.0) * 1000.0));
CHPBV_MinFL_PID_OP_PAPR.td := DINT_TO_TIME(REAL_TO_DINT(LIMIT(0.0, PID_MINFL_TD, 100000.0) * 1000.0));
CHPBV_MinFL_PID_OP_PAPR.td_lag := DINT_TO_TIME(REAL_TO_DINT(LIMIT(0.0, PID_MINFL_TD_LAG, 100000.0) * 1000.0));
CHPBV_MinFL_PID_OP_PAPR.ymax := PID_MINFL_YMAX;
CHPBV_MinFL_PID_OP_PAPR.ymin := PID_MINFL_YMIN;
CHPBV_MinFL_PID_OP_Mode.en_p := PID_MINFL_EN_P;
CHPBV_MinFL_PID_OP_Mode.en_i := PID_MINFL_EN_I;
CHPBV_MinFL_PID_OP_Mode.halt := (NOT CHPPV_MinFL_Enable) OR PID_MINFL_HALT;
(* CHWDT: charging chiller inlet temperature *)
CHPPV_MinCHWDT_PID_PARA.gain := PID_CHWDT_GAIN;
CHPPV_MinCHWDT_PID_PARA.ti := DINT_TO_TIME(REAL_TO_DINT(LIMIT(0.0, PID_CHWDT_TI, 100000.0) * 1000.0));
CHPPV_MinCHWDT_PID_PARA.td := DINT_TO_TIME(REAL_TO_DINT(LIMIT(0.0, PID_CHWDT_TD, 100000.0) * 1000.0));
CHPPV_MinCHWDT_PID_PARA.td_lag := DINT_TO_TIME(REAL_TO_DINT(LIMIT(0.0, PID_CHWDT_TD_LAG, 100000.0) * 1000.0));
CHPPV_MinCHWDT_PID_PARA.ymax := PID_CHWDT_YMAX;
CHPPV_MinCHWDT_PID_PARA.ymin := PID_CHWDT_YMIN;
CHPPV_MinCHWDT_PID_Mode.en_p := PID_CHWDT_EN_P;
CHPPV_MinCHWDT_PID_Mode.en_i := PID_CHWDT_EN_I;
CHPPV_MinCHWDT_PID_Mode.halt := (NOT CHPPV_MinCHWDT_Enable) OR PID_CHWDT_HALT;
(* TSTFL: charging tank flow *)
CHPPV_MinTST_FL_PID_PAPR.gain := PID_TSTFL_GAIN;
CHPPV_MinTST_FL_PID_PAPR.ti := DINT_TO_TIME(REAL_TO_DINT(LIMIT(0.0, PID_TSTFL_TI, 100000.0) * 1000.0));
CHPPV_MinTST_FL_PID_PAPR.td := DINT_TO_TIME(REAL_TO_DINT(LIMIT(0.0, PID_TSTFL_TD, 100000.0) * 1000.0));
CHPPV_MinTST_FL_PID_PAPR.td_lag := DINT_TO_TIME(REAL_TO_DINT(LIMIT(0.0, PID_TSTFL_TD_LAG, 100000.0) * 1000.0));
CHPPV_MinTST_FL_PID_PAPR.ymax := PID_TSTFL_YMAX;
CHPPV_MinTST_FL_PID_PAPR.ymin := PID_TSTFL_YMIN;
CHPPV_MinTST_FL_PID_MODE.en_p := PID_TSTFL_EN_P;
CHPPV_MinTST_FL_PID_MODE.en_i := PID_TSTFL_EN_I;
CHPPV_MinTST_FL_PID_MODE.halt := (NOT CHPPV_MinTST_FL_Enable) OR PID_TSTFL_HALT;

(* P06: feedback based, non-reversing sequence. Start/stop sections share P06_State.
   Existing bit arrays remain HMI/TES compatibility outputs, not state memory. *)
P06_ResetEdge := (P06_LocalReset OR SMCL_RESET) AND NOT P06_ResetOld;
P06_ResetOld := P06_LocalReset OR SMCL_RESET;
P06_TempValid := NOT (CHS_T01_UnderRange OR CHS_T01_OverRange)
    OR NOT (CHS_T02_UnderRange OR CHS_T02_OverRange);
P06_FlowValid := NOT (CHS_FL01_UnderRange OR CHS_FL01_OverRange);
P06_Path := ((CHV01_FB > CHV_OSTP) AND (CHV02_FB > CHV_OSTP))
    OR (CHV03_FB > CHV_OSTP);
P06_Water := CHP_RUN AND P06_FlowValid AND (CHS_FL01 > CH_INFL_MIN) AND P06_Path;
P06_RawFault := CHP_FLT_DI OR NOT CHP_REM OR ACH_F1 OR ACHF_F
    OR NOT ACH_AM OR ALM_CHP_MM OR ALM_ACH_MM OR ALM_CHBPV_MM
    OR ALM_CHV01_MM OR ALM_CHV02_MM OR ALM_CHV03_MM;
P06_ConfigFault := (CH_INFL_MIN <= 0.0) OR (CHV_OSTP <= 0.0)
    OR (CHV_OSTP >= 100.0) OR (STOP_PUMP_DELAY < 0)
    OR (STOP_PUMP_DELAY > 3600) OR (START_LOWFL_TM <= 0)
    OR (START_LOWFL_TM > 3600);

(* Timers execute once per scan, including fault/idle scans. Cold/warm resets
   only the non-retained sequence; min-off starts again conservatively. *)
IF ((P06_State = 30) OR (P06_State = 40)) AND NOT ACH_PWR THEN
    P06_PowerEvent := TRUE;
END_IF;
IF NOT ACH_EN OR (ACH_RUN AND ACH_PWR AND (P06_State = 40)) THEN
    P06_PowerEvent := FALSE;
END_IF;
P06_OffPreset := T#10m;
(* Enable only after the chiller vendor confirms this specific quick-restart
   contract. It never bypasses process interlocks, faults or post-run. *)
IF P06_FastRestartApproved AND P06_PowerEvent THEN P06_OffPreset := T#120s; END_IF;
P06_TOff(IN := NOT ACH_RUN AND NOT P06_Boot, PT := P06_OffPreset);
P06_TOn(IN := ACH_RUN AND NOT P06_Boot, PT := T#10m);
P06_TValve(IN := (P06_State = 10) AND NOT P06_Boot, PT := T#120s);
P06_TFlow(IN := (P06_State = 20) AND NOT P06_Boot,
    PT := DINT_TO_TIME(LIMIT(1, START_LOWFL_TM, 3600) * 1000));
P06_TStable(IN := P06_Water AND NOT P06_Boot, PT := T#10s);
P06_TChiller(IN := (P06_State = 30) AND NOT P06_Boot, PT := T#180s);
P06_TLostFlow(IN := ((P06_State = 30) OR (P06_State = 40))
    AND NOT P06_Water AND NOT P06_Boot, PT := T#2s);

IF P06_Boot THEN
    P06_State := 0;
    P06_ResetOld := UNIT_Reset OR SMCL_RESET;
    P06_ResetEdge := FALSE;
    IF ACH_RUN THEN
        IF P06_Water AND NOT P06_RawFault AND ACH_PWR AND NOT CH_MS THEN
            P06_State := 40;
        ELSE P06_State := 50;
        END_IF;
    ELSIF CHP_RUN THEN P06_State := 60;
    END_IF;
END_IF;
IF (P06_State <> 0) AND (P06_State <> 10) AND (P06_State <> 20)
    AND (P06_State <> 30) AND (P06_State <> 40) AND (P06_State <> 50)
    AND (P06_State <> 60) AND (P06_State <> 70) AND (P06_State <> 80)
    AND (P06_State <> 900) THEN
    P06_SeqFault := TRUE; P06_FaultCode := 99; P06_State := 50;
END_IF;
IF P06_ResetEdge AND NOT ACH_RUN AND NOT CHP_RUN AND NOT P06_RawFault
    AND ACH_PWR AND NOT P06_ConfigFault
    AND ((P06_State = 0) OR (P06_State = 900)) THEN
    P06_SeqFault := FALSE; P06_FaultCode := 0; P06_StopFault := FALSE;
    P06_State := 0;
END_IF;

(* A supply failure does not invent an equipment-fault latch. Stop commands;
   water/TES may continue on their own UPS supply while pumps remain healthy. *)
P06_Trip := P06_RawFault OR P06_ConfigFault OR P06_TLostFlow.Q;
IF ((P06_State = 10) OR (P06_State = 20) OR (P06_State = 30)
    OR (P06_State = 40)) AND P06_Trip THEN
    P06_SeqFault := TRUE;
    IF P06_ConfigFault THEN P06_FaultCode := 1;
    ELSIF P06_RawFault THEN P06_FaultCode := 2;
    ELSE P06_FaultCode := 3;
    END_IF;
    P06_State := 50;
END_IF;
IF ((P06_State = 10) OR (P06_State = 20) OR (P06_State = 30)
    OR (P06_State = 40)) AND NOT ACH_PWR THEN P06_State := 50; END_IF;
IF (P06_State = 40) AND NOT ACH_RUN AND NOT P06_Boot THEN
    P06_SeqFault := TRUE; P06_FaultCode := 4; P06_State := 50;
END_IF;
(* Maintenance requests an orderly stop. Only normal demand withdrawal waits
   MinOn; maintenance and process protection may stop the chiller immediately. *)
IF (CH_MS OR TST_MS) AND (P06_State > 0) AND (P06_State < 50) THEN P06_State := 50; END_IF;
IF NOT ACH_EN AND NOT P06_Boot THEN
    IF (P06_State = 10) OR (P06_State = 20) OR (P06_State = 30) THEN
        P06_State := 50;
    ELSIF (P06_State = 40) AND P06_TOn.Q THEN P06_State := 50;
    END_IF;
END_IF;

CASE P06_State OF
0:
    IF ACH_RUN THEN P06_State := 50;
    ELSIF ACH_EN AND NOT CH_MS AND NOT TST_MS AND NOT P06_SeqFault
        AND NOT P06_RawFault AND NOT P06_ConfigFault AND ACH_PWR
        AND NOT UNIT_NOA AND P06_TOff.Q AND P06_TempValid THEN
        START_TST_FULL := TST_CAP > TST_CAP_STP;
        P06_State := 10;
    END_IF;
10:
    IF (START_TST_FULL AND (CHV01_FB > CHV_OSTP) AND (CHV02_FB > CHV_OSTP))
        OR (NOT START_TST_FULL AND (CHV03_FB > CHV_OSTP)) THEN
        P06_State := 20;
    ELSIF P06_TValve.Q THEN
        P06_SeqFault := TRUE; P06_FaultCode := 10; P06_State := 50;
    END_IF;
20:
    IF P06_TStable.Q THEN P06_State := 30;
    ELSIF P06_TFlow.Q THEN
        P06_SeqFault := TRUE; P06_FaultCode := 20; P06_State := 50;
    END_IF;
30:
    IF ACH_RUN THEN P06_State := 40;
    ELSIF P06_TChiller.Q THEN
        P06_SeqFault := TRUE; P06_FaultCode := 30; P06_State := 50;
    END_IF;
900:
    IF ACH_RUN THEN P06_State := 50; END_IF;
END_CASE;

FOR I := 0 TO 5 DO Chiller_Start_ENA[I] := FALSE; END_FOR;
Chiller_Start_ENA[1] := P06_State = 10;
Chiller_Start_ENA[2] := P06_State = 20;
Chiller_Start_ENA[3] := P06_State = 30;
Chiller_Start_ENA[4] := P06_State = 40;
START_ACH_REQ := ((P06_State = 30) OR (P06_State = 40))
    AND ACH_PWR AND NOT P06_Trip AND NOT P06_SeqFault AND NOT CH_MS;
(* New starts require current water proof; running loss uses the 2 s debounce. *)
IF (P06_State = 30) AND NOT P06_Water THEN START_ACH_REQ := FALSE; END_IF;
START_PUMP_REQ := (P06_State >= 20) AND (P06_State <= 40);
ALM_START_LOWFL := P06_SeqFault AND (P06_FaultCode = 20);

(* P06: no restart reversal while stopping; actual feedback controls post-run. *)
P06_TStop(IN := (P06_State = 50) AND NOT P06_Boot, PT := T#180s);
P06_TPost(IN := (P06_State = 60) AND NOT ACH_RUN AND NOT P06_Boot,
    PT := DINT_TO_TIME(LIMIT(0, STOP_PUMP_DELAY, 3600) * 1000));
P06_TPumpStop(IN := (P06_State = 70) AND NOT P06_Boot, PT := T#60s);
(* A chiller-only failure must not discard useful TES cooling while the SMCL
   is proving the replacement. Pump/process faults and maintenance still win. *)
P06_TESHold := ACH_EN AND NOT CH_MS AND NOT TST_MS AND NOT P06_ConfigFault
    AND NOT CHP_FLT_DI AND CHP_REM AND NOT ALM_CHP_MM
    AND P06_Water AND (TST_MODE = 3) AND (TST_CAP > TST_CAP_MINSTP);
IF ACH_RUN AND ((P06_State = 60) OR (P06_State = 70)
    OR (P06_State = 80) OR (P06_State = 900)) THEN
    P06_SeqFault := TRUE; P06_FaultCode := 51; P06_State := 50;
END_IF;
CASE P06_State OF
50:
    IF NOT ACH_RUN THEN
        IF CHP_RUN THEN P06_State := 60; ELSE P06_State := 70; END_IF;
    ELSIF P06_TStop.Q THEN
        P06_StopFault := TRUE; P06_SeqFault := TRUE; P06_FaultCode := 50;
    END_IF;
60:
    IF P06_TPost.Q AND NOT P06_TESHold THEN P06_State := 70; END_IF;
70:
    IF NOT CHP_RUN THEN P06_State := 80;
    ELSIF P06_TPumpStop.Q THEN
        P06_StopFault := TRUE; P06_SeqFault := TRUE; P06_FaultCode := 70;
    END_IF;
80:
    IF P06_SeqFault THEN P06_State := 900; ELSE P06_State := 0; END_IF;
END_CASE;
FOR I := 0 TO 5 DO Chiller_Stop_ENA[I] := FALSE; END_FOR;
Chiller_Stop_ENA[1] := P06_State = 50;
Chiller_Stop_ENA[2] := P06_State = 60;
Chiller_Stop_ENA[3] := P06_State = 70;
Chiller_Stop_ENA[5] := (P06_State = 0) OR (P06_State = 900);
STOP_PUMP_HOLD := (P06_State = 50) OR (P06_State = 60);
P06_Isolatable := CH_MS AND NOT ACH_RUN AND NOT CHP_RUN
    AND ((P06_State = 0) OR (P06_State = 900));
START_ACH_REQ := START_ACH_REQ AND ((P06_State = 30) OR (P06_State = 40));
START_PUMP_REQ := (P06_State >= 20) AND (P06_State <= 40);

(* Thermal storage tank mode (rewritten per SOO). Valve actions are in section OUT_ARB.
   Start done: TST-CAP > 85% -> normal, else -> bypass
   Normal/charge -> discharge: chiller power loss or fault while the pump runs (alarm)
   Discharge -> bypass: TST-CAP < 20% or CHS-T02 > setpoint + 1.7 °C for 30 s
   Discharge -> normal: chiller running again
   Normal/bypass -> charge: chiller running, CHS=ON, header supply < setpoint + 1.1 °C for 15 min, TST-CAP < 95%
   Charge -> normal: TST-CAP > 95% and all 4 tank temps < setpoint + 0.8 °C
   Charge -> bypass: chiller stopped normally
   Bypass -> normal: chiller running and TST-CAP >= 95% *)
TST_INIT_TRIG (CLK := Chiller_Start_ENA[4], Q => TST_INIT);
(* user 2026-10-15: TES maintenance switched off -> decide the TES mode again *)
TST_MS_F_TRIG (CLK := TST_MS, Q => TST_MS_INIT);
IF TST_MS THEN
    TST_MODE := 0;
ELSE
    IF (TST_INIT OR TST_MS_INIT) AND (TST_MODE = 0) THEN
        IF TST_CAP > TST_CAP_STP THEN TST_MODE := 2; ELSE TST_MODE := 1; END_IF;
    END_IF;

    (* 2026-10-15: chiller lost (no power / fault) while the tank has no usable capacity (TST-CAP below the discharge
       minimum, typically during charging): discharging is pointless and the mode toggled 1 <-> 3. Go to bypass,
       latch TST_NOCAP = unit not available (UNIT_ENABLE FALSE) -> SMCL starts the next unit and stops this one
       after the handover (supply temperature reached). Cleared when the unit is stopped (ACH_EN removed). *)
    IF ((TST_MODE = 2) OR (TST_MODE = 4) OR (TST_MODE = 3)) AND CHP_RUN AND ((NOT ACH_PWR) OR ACH_Fault)
       AND (TST_CAP < TST_CAP_MINSTP) THEN
        TST_NOCAP := TRUE;
    END_IF;
    IF TST_NOCAP THEN
        TST_MODE := 1;
    ELSIF ((TST_MODE = 2) OR (TST_MODE = 4)) AND CHP_RUN AND ((NOT ACH_PWR) OR ACH_Fault) THEN
        TST_MODE := 3;
    END_IF;

    TST_DtB_Condition (Condition := (TST_MODE = 3) AND ((TST_CAP < TST_CAP_MINSTP) OR (CHS_T02 > CHS_TSP_OUT + TSTDT)),
                       SP_Condition_Delay := TST_TIME, SEC_P := SEC_P, Condition_OK => TST_DtB_OK);
    IF TST_DtB_OK THEN TST_MODE := 1; END_IF;

    IF (TST_MODE = 3) AND ACH_RUN AND ACH_PWR AND NOT ACH_Fault THEN TST_MODE := 2; END_IF;

    (* 2026-10-20 user (ACH-01 edit): no CHS in the condition *)
    TST_BtC_Condition (Condition := ((TST_MODE = 1) OR (TST_MODE = 2)) AND ACH_RUN
                                    AND (CHWS_T01_T02 < CHS_TSP_OUT + TDM_CHWS_DT) AND (TST_CAP < TST_CAP_MAXSTP),
                       SP_Condition_Delay := TDMCHWS_TIME1, SEC_P := SEC_P, Condition_OK => TST_BtC_OK);
    IF TST_BtC_OK THEN TST_MODE := 4; END_IF;

    TST_FULL := (TST_CAP > TST_CAP_MAXSTP) AND (TST_T01 < CHS_TSP_OUT + TST_DT) AND (TST_T02 < CHS_TSP_OUT + TST_DT)
                AND (TST_T03 < CHS_TSP_OUT + TST_DT) AND (TST_T04 < CHS_TSP_OUT + TST_DT);
    IF (TST_MODE = 4) AND TST_FULL THEN TST_MODE := 2; END_IF;
    IF (TST_MODE = 4) AND (NOT ACH_RUN) AND ACH_PWR AND NOT ACH_Fault THEN TST_MODE := 1; END_IF;
    IF (TST_MODE = 1) AND ACH_RUN AND (TST_CAP >= TST_CAP_MAXSTP) THEN TST_MODE := 2; END_IF;

    (* no-capacity latch: keep bypass whatever the transitions above did; cleared once the unit is stopped *)
    (* 2026-10-20 user (ACH-01 edit): also cleared once the chiller runs again *)
    IF NOT ACH_EN OR ACH_RUN THEN TST_NOCAP := FALSE; END_IF;
    IF TST_NOCAP THEN TST_MODE := 1; END_IF;
    (* Unit disabled and pump stopped: clear the mode *)
    IF (NOT ACH_EN) AND (NOT CHP_RUN) THEN TST_MODE := 0; END_IF;
END_IF;

DISCH_ALM := TST_MODE = 3;
TST_ENA[0] := TST_MODE = 1;
TST_ENA[1] := TST_MODE = 2;
TST_ENA[2] := TST_MODE = 3;
TST_ENA[3] := TST_MODE = 4;

(* Freeze protection mode (rewritten per SOO)
   Enter (any, standby units only, FPM-ENA on): OA-T < -5 °C; lowest water temp < -2.2 °C; EVAP-PUMP=ON
   Exit (all): OA-T > -5 + 1.1; lowest water temp > -2.2 + 1.1; EVAP-PUMP=OFF; or the unit is asked to run
   Action: CHV02 -> 17%, CHV01, CHBPV -> 100%; then pump at minimum speed for 5 min; after the pump stops valves return to standby 100%
   Repeat every FPM_REPEAT_TM while the condition lasts (not in SOO, added) *)
FPM_STANDBY := ((P06_State = 0) OR (P06_State = 900)) AND (NOT ACH_EN) AND (NOT ACH_RUN) AND (NOT CH_MS) AND (NOT TST_MS) AND CMD_FPM_ENA;
CH_Min_T := MIN(LCHLT, ECHLT, CHS_T01, CHS_T02, CHR_T01, CHIN_T01);
FPM_ENA[2] := OA_T < FPM_OA_IN_TSP;
(* 2026-10-19 (user): hysteresis FPM_IN_DTSP on the water temperature condition *)
IF CH_Min_T < FPM_IN_TSP THEN
  FPM_ENA[3] := TRUE;
END_IF;
IF CH_Min_T > FPM_IN_TSP + FPM_IN_DTSP THEN
  FPM_ENA[3] := FALSE;
END_IF;
FPM_ENA[4] := EVAP_PUMP;
FPM_CLR := (OA_T > FPM_OA_IN_TSP + FPM_OA_IN_TSP_plus) AND (CH_Min_T > FPM_IN_TSP + FPM_IN_TSP_plus) AND NOT EVAP_PUMP;
(* 2026-10-15: same as the chemical mode - pump cannot run or a valve does not follow -> leave the anti-freeze mode,
   no new start until the cause is gone (alarm reset) *)
IF FPM_ENA[0] AND (CHWP_Fault OR ALM_CHP_MM OR ALM_CHV01_MM OR ALM_CHV02_MM OR ALM_CHBPV_MM) THEN
    FPM_FAIL := TRUE;
END_IF;
IF ACH_EN OR NOT (CHWP_Fault OR ALM_CHP_MM OR ALM_CHV01_MM OR ALM_CHV02_MM OR ALM_CHBPV_MM) THEN
    IF NOT FPM_ENA[0] THEN FPM_FAIL := FALSE; END_IF;
END_IF;
IF FPM_STANDBY AND (FPM_ENA[2] OR FPM_ENA[3] OR FPM_ENA[4]) AND NOT FPM_FAIL THEN FPM_ENA[0] := TRUE; END_IF;
IF (NOT FPM_STANDBY) OR FPM_CLR OR FPM_FAIL THEN FPM_ENA[0] := FALSE; END_IF;
FPM_ENA[1] := FPM_STANDBY;

FPM_ENA_TRIG (CLK := FPM_ENA[0], Q => FPM_ENA[5]);
FPM_RPT (Condition := FPM_ENA[0] AND NOT FPM_ENA[6] AND NOT FPM_ENA[7], SP_Condition_Delay := FPM_REPEAT_TM,
         SEC_P := SEC_P, Condition_OK => FPM_RPT_OK);
IF FPM_ENA[5] OR FPM_RPT_OK THEN
    FPM_ENA[6] := TRUE;          (* valves moving to position *)
END_IF;
IF FPM_ENA[6] AND (CHV01_FB > CHV_OSTP) AND (CHV02_FB < CHV_FPM_SP + 5.0) AND (CHBPV_FB > CHBPV_FPM_SP - 5.0) THEN
    FPM_ENA[6] := FALSE;
    FPM_ENA[7] := TRUE;          (* pump running *)
END_IF;
FPM_PULSE (Condition := FPM_ENA[7], SP_Condition_Delay := FPM_CH_PULSE, SEC_P := SEC_P, Condition_OK => FPM_PULSE_OK);
IF FPM_PULSE_OK THEN FPM_ENA[7] := FALSE; END_IF;
IF NOT FPM_ENA[0] THEN
    FPM_ENA[5] := FALSE; FPM_ENA[6] := FALSE; FPM_ENA[7] := FALSE;
END_IF;
FPM_VALVE_REQ := FPM_ENA[6] OR FPM_ENA[7];
FPM_PUMP_REQ := FPM_ENA[7];

FPM_LOWFL_C (Condition := FPM_ENA[7] AND CHP_RUN AND (CHS_FL01 < CH_INFL_MIN - 10.0), SP_Condition_Delay := 180,
             SEC_P := SEC_P, Condition_OK => ALM_FPM_LOWFL);

(* Chemical water treatment (rewritten per SOO)
   Chiller and pump stopped longer than 3 days (CHE-IN-DELAY) and no other unit in chemical treatment -> CHV01, CHBPV to 60%, then pump at minimum speed for 3 min, chiller stays off
   Fix: delay x86400; pump command wired to OUT_ARB; added 3 min timer; abort at once when the unit is asked to run / maintenance / freeze protection *)
(* 2026-10-19 (user): CHV01 100 % (CHV_CHE is the CHBPV position only) - with CHV02 closed CHBPV alone has no flow path *)
CHE_IDLE := (NOT ACH_RUN) AND (NOT CHP_RUN) AND (NOT ACH_EN);
(* K: test divider for the delay (user, 2026-10-15 bench test); 1 = days as set; MAX guards against K = 0 *)
Chemical_Mode_Condition (Condition := CHE_IDLE AND NOT CH_MS, SP_Condition_Delay := SP_Chemical_Mode_Delay * 86400 / MAX(K, 1),
                         SEC_P := SEC_P, Condition_OK => CHE_DUE);
CHE_ABORT := ACH_EN OR CH_MS OR TST_MS OR FPM_ENA[0];
(* 2026-10-15: the pump cannot run (fault / mismatch / not remote) or a valve does not follow -> leave the chemical mode
   instead of waiting for the 3 min pump run forever; no new start until the cause is gone (alarm reset) *)
IF Chemical_Mode_ENA[0] AND (CHWP_Fault OR ALM_CHP_MM OR ALM_CHV01_MM OR ALM_CHBPV_MM) THEN
    CHE_FAIL := TRUE;
END_IF;
IF ACH_EN OR NOT (CHWP_Fault OR ALM_CHP_MM OR ALM_CHV01_MM OR ALM_CHBPV_MM) THEN
    IF NOT Chemical_Mode_ENA[0] THEN CHE_FAIL := FALSE; END_IF;
END_IF;
CHE_ABORT := CHE_ABORT OR CHE_FAIL;
IF CHE_DUE AND P06_ChemGrant AND (P06_State = 0) AND (NOT Chemical_Mode_ENA[0]) AND (NOT Other_Chemical_Mode_Runing) AND NOT CHE_ABORT THEN
    Chemical_Mode_ENA[0] := TRUE;
    Chemical_Mode_ENA[3] := TRUE;      (* valves moving to position *)
END_IF;
IF Chemical_Mode_ENA[3] AND (CHV01_FB > 95.0) AND (CHBPV_FB > CHV_CHE - 5.0) THEN
    Chemical_Mode_ENA[3] := FALSE;
    Chemical_Mode_ENA[4] := TRUE;      (* pump running *)
END_IF;
Chemical_Stop_Condition (Condition := Chemical_Mode_ENA[4] AND CHP_RUN, SP_Condition_Delay := CHE_CH_PLUSE,
                         SEC_P := SEC_P, Condition_OK => CHE_DONE);
IF CHE_DONE OR CHE_ABORT THEN
    Chemical_Mode_ENA[0] := FALSE;
    Chemical_Mode_ENA[3] := FALSE;
    Chemical_Mode_ENA[4] := FALSE;
END_IF;

(* Pipe heat tracing: start when any temperature < PHTS_T_SP (5 °C); stop when all > setpoint + hysteresis (1.1 °C). Fixed T04 <> to > *)
IF (PHTS_T01 < PHTS_T_SP) OR (PHTS_T02 < PHTS_T_SP) OR (PHTS_T03 < PHTS_T_SP) OR (PHTS_T04 < PHTS_T_SP) THEN
    PHTS_Auto_OP := TRUE;
END_IF;
IF (PHTS_T01 > PHTS_T_SP + PHTS_DT_SP) AND (PHTS_T02 > PHTS_T_SP + PHTS_DT_SP)
   AND (PHTS_T03 > PHTS_T_SP + PHTS_DT_SP) AND (PHTS_T04 > PHTS_T_SP + PHTS_DT_SP) THEN
    PHTS_Auto_OP := FALSE;
END_IF;

(* Output arbitration (all auto commands in one place so sections do not overwrite each other)
   Valve priority: unit maintenance > tank maintenance > freeze protection > chemical treatment > start step 1 > tank mode > standby (CHV01/02/CHBPV 100%)
   Fix: bypass valve uses CHBPV_Auto_OP everywhere (FPM/chemical sections wrote CHBPV while the drive block read CHPBV); PID enable recalculated every scan *)
(* 2026-10-19 (user): CHV03-only lineup (bypass mode, or start step 1 with TES not full) - when the minimum flow PID
   opens CHBPV (> BYP_CHV01_ON), CHV01 goes to 100 %; back to closed when CHBPV has been < BYP_CHV01_OFFP
   for BYP_CHV01_TM or the lineup is left. Same branch conditions as the arbitration below. *)
BYP_LINEUP := FALSE;
IF NOT (CH_MS OR TST_MS OR FPM_VALVE_REQ OR Chemical_Mode_ENA[0]) THEN
    IF Chiller_Start_ENA[1] OR (ACH_EN AND (TST_MODE = 0) AND NOT TST_MS) THEN
        BYP_LINEUP := NOT START_TST_FULL;
    ELSIF TST_MODE = 1 THEN
        BYP_LINEUP := TRUE;
    END_IF;
END_IF;
IF BYP_LINEUP AND (CHPBV_MinFL_PID_OP > BYP_CHV01_ON) THEN
    BYP_CHV01 := TRUE;
END_IF;
BYP_CHV01_OFF (Condition := CHPBV_MinFL_PID_OP < BYP_CHV01_OFFP, SP_Condition_Delay := BYP_CHV01_TM, SEC_P := SEC_P, Condition_OK => BYP_CHV01_OFF_OK);
IF (NOT BYP_LINEUP) OR BYP_CHV01_OFF_OK THEN
    BYP_CHV01 := FALSE;
END_IF;
V1 := CHV01_Auto_OP; V2 := CHV02_Auto_OP; V3 := CHV03_Auto_OP; VB := CHBPV_Auto_OP;
CHPPV_MinFL_Enable := FALSE;
CHPPV_MinTST_FL_Enable := FALSE;
CHPPV_MinCHWDT_Enable := FALSE;

IF P06_Isolatable THEN
    V1 := 0.0; V2 := 0.0; V3 := 0.0; VB := 0.0;
ELSIF (P06_State >= 50) AND (P06_State <= 70) THEN
    (* Keep the last proven lineup through actual stop and pump post-run. *)
    V1 := CHV01_Auto_OP; V2 := CHV02_Auto_OP;
    V3 := CHV03_Auto_OP; VB := CHBPV_Auto_OP;
ELSIF TST_MS AND NOT ACH_RUN AND NOT CHP_RUN THEN
    V1 := CHV01_MS_OP; V2 := CHV02_MS_OP; V3 := CHV03_MS_OP; VB := CHBPV_MS_OP;
ELSIF FPM_VALVE_REQ THEN
    (* 2026-10-19 (user): CHV01 always 100 % - with CHV02 closed there is no flow path through CHBPV otherwise *)
    V1 := 100.0; V2 := CHV_FPM_SP; VB := CHBPV_FPM_SP; V3 := CHV_FPM_SP;
ELSIF Chemical_Mode_ENA[0] THEN
    V1 := 100.0; VB := CHV_CHE; V2 := 0.0; V3 := 0.0;
ELSIF Chiller_Start_ENA[1] OR (ACH_EN AND (TST_MODE = 0) AND NOT TST_MS) THEN
    CHPPV_MinFL_Enable := TRUE;
    VB := CHPBV_MinFL_PID_OP;
    IF START_TST_FULL THEN
        V1 := 100.0; V2 := 100.0;
        IF (CHV01_FB > CHV_OSTP) AND (CHV02_FB > CHV_OSTP) THEN V3 := 0.0; END_IF;
    ELSE
        V3 := 100.0;
        IF CHV03_FB > CHV_OSTP THEN
            V2 := 0.0;
            IF BYP_CHV01 THEN V1 := 100.0; ELSE V1 := 0.0; END_IF;
        END_IF;
    END_IF;
ELSIF TST_MODE = 1 THEN             (* Bypass *)
    V3 := 100.0;
    (* 2026-10-19 (user): CHBPV opened by the minimum flow PID -> CHV01 100 % (flow path through CHBPV), CHV02 stays closed *)
    IF CHV03_FB > CHV_OSTP THEN
        V2 := 0.0;
        IF BYP_CHV01 THEN V1 := 100.0; ELSE V1 := 0.0; END_IF;
    END_IF;
    CHPPV_MinFL_Enable := TRUE;
    VB := CHPBV_MinFL_PID_OP;
ELSIF TST_MODE = 2 THEN             (* Normal cooling *)
    V1 := 100.0; V2 := 100.0;
    IF (CHV01_FB > CHV_OSTP) AND (CHV02_FB > CHV_OSTP) THEN V3 := 0.0; END_IF;
    CHPPV_MinFL_Enable := TRUE;
    VB := CHPBV_MinFL_PID_OP;
ELSIF TST_MODE = 3 THEN             (* Discharge *)
    V1 := 100.0; V2 := 100.0;
    IF (CHV01_FB > CHV_OSTP) AND (CHV02_FB > CHV_OSTP) THEN V3 := 0.0; END_IF;
    VB := 0.0;
ELSIF TST_MODE = 4 THEN             (* Charge *)
    V1 := 100.0; V3 := 100.0;
    IF (CHV01_FB > CHV_OSTP) AND (CHV03_FB > CHV_OSTP) THEN V2 := 0.0; END_IF;
    CHPPV_MinTST_FL_Enable := TRUE;
    CHPPV_MinCHWDT_Enable := TRUE;
    VB := MIN(CHPPV_MinCHWDT_PID_OP, CHPPV_MinTST_FL_PID_OP);
ELSE                                (* standby: CHV01/CHV02/CHV03 100%, CHBPV 0% (2026-10-19 user) *)
    V1 := 100.0; V2 := 100.0; V3 := 100.0; VB := 0.0;
END_IF;
CHV01_Auto_OP := V1; CHV02_Auto_OP := V2; CHV03_Auto_OP := V3; CHBPV_Auto_OP := VB;
(* PID halt flags: see PID_PARA *)

(* Pumps and chillers *)
(* 2026-10-15 bench test (user): no MM / line-up interlock on the auto outputs here *)
(* 2026-10-20 user (ACH-01 edit): anti-freeze / chemical pump request held 40 s after it drops *)
PUMP_REQ := FPM_PUMP_REQ OR Chemical_Mode_ENA[4];
TOF_PUMP_OFF (IN := PUMP_REQ, PT := T#40s, Q => PUMP_REQ_OUT);
(* 2026-10-22 user (ACH-01 of 10-22): the water path interlock CHP_Shutdown of 10-21 is removed again *)
CHP_Auto_OP := (START_PUMP_REQ OR STOP_PUMP_HOLD OR PUMP_REQ_OUT)
               AND NOT CHP_FLT_DI AND CHP_REM AND NOT P06_Isolatable;
ACH_Auto_OP := START_ACH_REQ AND NOT CH_MS AND NOT TST_MS
    AND NOT P06_SeqFault AND NOT P06_ConfigFault;
IF FPM_PUMP_REQ OR Chemical_Mode_ENA[4] THEN
    CHPVSD_Auto_OP := CHP_MIN;
ELSE
    CHPVSD_Auto_OP := MAX(CHVSD_SEQ_OUT, CHP_MIN);
END_IF;

(* Chiller leaving water setpoint: written to chiller register 1 over Modbus RTU (Modbus_RTU_COMM step 7); ACH_TSP is for display only *)
ACH_TSP := CHS_TSP_OUT;

(* P06 final physical-output guard executes AFTER Drive_OP, including manual
   software commands. Independent manufacturer/hardwired safeties remain. *)
P06_AuxPath := (CHV01_FB > CHV_OSTP) AND (CHBPV_FB > 5.0);
P06_RunSafe := ACH_PWR AND ACH_AM AND NOT ACH_F1 AND NOT ACHF_F
    AND NOT CHP_FLT_DI AND CHP_REM AND NOT ALM_CHP_MM
    AND P06_Water AND NOT P06_SeqFault AND NOT P06_ConfigFault
    AND NOT CH_MS AND NOT TST_MS AND (ACH_RUN OR P06_TOff.Q);
IF NOT P06_RunSafe THEN ACH_STC := FALSE; ACH_SPC := TRUE; END_IF;
IF CHP_FLT_DI OR NOT CHP_REM OR ALM_CHP_MM
    OR NOT (P06_Path OR P06_AuxPath) OR P06_Isolatable THEN
    CHP_STC := FALSE; CHP_SPC := TRUE;
END_IF;

CHPVSD_C_ANA (PV_Real := CHPVSD_C, EU_Max := 100.0, EU_Min := 0.0, Raw_High := 10000.0, Raw_Low := 0.0, AO_Raw => M5_AQ0);
CHV01_C_ANA (PV_Real := CHV01_C, EU_Max := 100.0, EU_Min := 0.0, Raw_High := 10000.0, Raw_Low := 0.0, AO_Raw => M5_AQ1);
CHV02_C_ANA (PV_Real := CHV02_C, EU_Max := 100.0, EU_Min := 0.0, Raw_High := 10000.0, Raw_Low := 0.0, AO_Raw => M5_AQ2);
CHV03_C_ANA (PV_Real := CHV03_C, EU_Max := 100.0, EU_Min := 0.0, Raw_High := 10000.0, Raw_Low := 0.0, AO_Raw => M5_AQ3);
CHBPV_C_ANA (PV_Real := CHBPV_C, EU_Max := 100.0, EU_Min := 0.0, Raw_High := 10000.0, Raw_Low := 0.0, AO_Raw => M5_AQ4);
(* 2026-10-15 bench test (user): chiller setpoint also output on AO channel 6 (0..100 -> 0..10000), besides the Modbus write *)
ACH_TSP_ANA (PV_Real := CHS_TSP_OUT, EU_Max := 100.0, EU_Min := 0.0, Raw_High := 10000.0, Raw_Low := 0.0, AO_Raw => M5_AQ6);

(* Unit level alarms (SOO section 3); maintenance masks the other alarms (3.2.7) *)
CHS_DEV_H_C (Condition := ACH_RUN AND ((CHS_T01 > CHS_TSP_OUT + CHS_TSP_OUT_plus) OR (CHS_T02 > CHS_TSP_OUT + CHS_TSP_OUT_plus)),
             SP_Condition_Delay := CHS_DEV_TM, SEC_P := SEC_P, Condition_OK => ALM_CHS_DEV_H);
CHS_DEV_L_C (Condition := ACH_RUN AND ((CHS_T01 < CHS_TSP_OUT - CHS_TSP_OUT_plus) OR (CHS_T02 < CHS_TSP_OUT - CHS_TSP_OUT_plus)),
             SP_Condition_Delay := CHS_DEV_TM, SEC_P := SEC_P, Condition_OK => ALM_CHS_DEV_L);
ALM_CH_MS := CH_MS;
ALM_NO_PWR := NOT ACH_PWR AND NOT CH_MS;
ALM_CHP_NOT_AUTO := NOT CHP_REM AND NOT CH_MS;
ALM_INHALE_CLOSE := ACH_ALM_CODE = 53;
ALM_INHALE_OPEN := ACH_ALM_CODE = 54;
ALM_UNIT_ANY := NOT CH_MS AND (ACH_Fault OR CHWP_Fault OR ALM_CHBPV_MM OR ALM_CHV01_MM OR ALM_CHV02_MM OR ALM_CHV03_MM
                OR ALM_CHS_DEV_H OR ALM_CHS_DEV_L OR ALM_START_LOWFL OR ALM_FPM_LOWFL OR ALM_NO_PWR OR DISCH_ALM
                OR ALM_SMCL_COMM OR PHTS_FLT OR VFD_ALM OR VFD_NOT_AUTO OR ACH_EVAP_FRZ OR ALM_INHALE_CLOSE OR ALM_INHALE_OPEN
                OR COMM_ACH_FAIL OR COMM_VFD_FAIL OR COMM_TST_FAIL OR TST_GEN_F);
(* Valve position alarms (2026-10-20): LL / L / H / HH of the valve feedbacks and commands, alarm only *)
VLA_CHV01_FB_LL (Condition := NOT CH_MS AND ((CHV01_FB <= ALM_CHV01_FB_LL_SP) OR (ALM_CHV01_FB_LL AND (CHV01_FB < ALM_CHV01_FB_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV01_FB_LL);
VLA_CHV01_FB_L (Condition := NOT CH_MS AND ((CHV01_FB <= ALM_CHV01_FB_L_SP) OR (ALM_CHV01_FB_L AND (CHV01_FB < ALM_CHV01_FB_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV01_FB_L);
VLA_CHV01_FB_H (Condition := NOT CH_MS AND ((CHV01_FB >= ALM_CHV01_FB_H_SP) OR (ALM_CHV01_FB_H AND (CHV01_FB > ALM_CHV01_FB_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV01_FB_H);
VLA_CHV01_FB_HH (Condition := NOT CH_MS AND ((CHV01_FB >= ALM_CHV01_FB_HH_SP) OR (ALM_CHV01_FB_HH AND (CHV01_FB > ALM_CHV01_FB_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV01_FB_HH);
VLA_CHV02_FB_LL (Condition := NOT CH_MS AND ((CHV02_FB <= ALM_CHV02_FB_LL_SP) OR (ALM_CHV02_FB_LL AND (CHV02_FB < ALM_CHV02_FB_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV02_FB_LL);
VLA_CHV02_FB_L (Condition := NOT CH_MS AND ((CHV02_FB <= ALM_CHV02_FB_L_SP) OR (ALM_CHV02_FB_L AND (CHV02_FB < ALM_CHV02_FB_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV02_FB_L);
VLA_CHV02_FB_H (Condition := NOT CH_MS AND ((CHV02_FB >= ALM_CHV02_FB_H_SP) OR (ALM_CHV02_FB_H AND (CHV02_FB > ALM_CHV02_FB_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV02_FB_H);
VLA_CHV02_FB_HH (Condition := NOT CH_MS AND ((CHV02_FB >= ALM_CHV02_FB_HH_SP) OR (ALM_CHV02_FB_HH AND (CHV02_FB > ALM_CHV02_FB_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV02_FB_HH);
VLA_CHV03_FB_LL (Condition := NOT CH_MS AND ((CHV03_FB <= ALM_CHV03_FB_LL_SP) OR (ALM_CHV03_FB_LL AND (CHV03_FB < ALM_CHV03_FB_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV03_FB_LL);
VLA_CHV03_FB_L (Condition := NOT CH_MS AND ((CHV03_FB <= ALM_CHV03_FB_L_SP) OR (ALM_CHV03_FB_L AND (CHV03_FB < ALM_CHV03_FB_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV03_FB_L);
VLA_CHV03_FB_H (Condition := NOT CH_MS AND ((CHV03_FB >= ALM_CHV03_FB_H_SP) OR (ALM_CHV03_FB_H AND (CHV03_FB > ALM_CHV03_FB_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV03_FB_H);
VLA_CHV03_FB_HH (Condition := NOT CH_MS AND ((CHV03_FB >= ALM_CHV03_FB_HH_SP) OR (ALM_CHV03_FB_HH AND (CHV03_FB > ALM_CHV03_FB_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV03_FB_HH);
VLA_CHBPV_FB_LL (Condition := NOT CH_MS AND ((CHBPV_FB <= ALM_CHBPV_FB_LL_SP) OR (ALM_CHBPV_FB_LL AND (CHBPV_FB < ALM_CHBPV_FB_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHBPV_FB_LL);
VLA_CHBPV_FB_L (Condition := NOT CH_MS AND ((CHBPV_FB <= ALM_CHBPV_FB_L_SP) OR (ALM_CHBPV_FB_L AND (CHBPV_FB < ALM_CHBPV_FB_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHBPV_FB_L);
VLA_CHBPV_FB_H (Condition := NOT CH_MS AND ((CHBPV_FB >= ALM_CHBPV_FB_H_SP) OR (ALM_CHBPV_FB_H AND (CHBPV_FB > ALM_CHBPV_FB_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHBPV_FB_H);
VLA_CHBPV_FB_HH (Condition := NOT CH_MS AND ((CHBPV_FB >= ALM_CHBPV_FB_HH_SP) OR (ALM_CHBPV_FB_HH AND (CHBPV_FB > ALM_CHBPV_FB_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHBPV_FB_HH);
VLA_CHV01_C_LL (Condition := NOT CH_MS AND ((CHV01_C <= ALM_CHV01_C_LL_SP) OR (ALM_CHV01_C_LL AND (CHV01_C < ALM_CHV01_C_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV01_C_LL);
VLA_CHV01_C_L (Condition := NOT CH_MS AND ((CHV01_C <= ALM_CHV01_C_L_SP) OR (ALM_CHV01_C_L AND (CHV01_C < ALM_CHV01_C_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV01_C_L);
VLA_CHV01_C_H (Condition := NOT CH_MS AND ((CHV01_C >= ALM_CHV01_C_H_SP) OR (ALM_CHV01_C_H AND (CHV01_C > ALM_CHV01_C_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV01_C_H);
VLA_CHV01_C_HH (Condition := NOT CH_MS AND ((CHV01_C >= ALM_CHV01_C_HH_SP) OR (ALM_CHV01_C_HH AND (CHV01_C > ALM_CHV01_C_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV01_C_HH);
VLA_CHV02_C_LL (Condition := NOT CH_MS AND ((CHV02_C <= ALM_CHV02_C_LL_SP) OR (ALM_CHV02_C_LL AND (CHV02_C < ALM_CHV02_C_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV02_C_LL);
VLA_CHV02_C_L (Condition := NOT CH_MS AND ((CHV02_C <= ALM_CHV02_C_L_SP) OR (ALM_CHV02_C_L AND (CHV02_C < ALM_CHV02_C_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV02_C_L);
VLA_CHV02_C_H (Condition := NOT CH_MS AND ((CHV02_C >= ALM_CHV02_C_H_SP) OR (ALM_CHV02_C_H AND (CHV02_C > ALM_CHV02_C_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV02_C_H);
VLA_CHV02_C_HH (Condition := NOT CH_MS AND ((CHV02_C >= ALM_CHV02_C_HH_SP) OR (ALM_CHV02_C_HH AND (CHV02_C > ALM_CHV02_C_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV02_C_HH);
VLA_CHV03_C_LL (Condition := NOT CH_MS AND ((CHV03_C <= ALM_CHV03_C_LL_SP) OR (ALM_CHV03_C_LL AND (CHV03_C < ALM_CHV03_C_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV03_C_LL);
VLA_CHV03_C_L (Condition := NOT CH_MS AND ((CHV03_C <= ALM_CHV03_C_L_SP) OR (ALM_CHV03_C_L AND (CHV03_C < ALM_CHV03_C_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV03_C_L);
VLA_CHV03_C_H (Condition := NOT CH_MS AND ((CHV03_C >= ALM_CHV03_C_H_SP) OR (ALM_CHV03_C_H AND (CHV03_C > ALM_CHV03_C_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV03_C_H);
VLA_CHV03_C_HH (Condition := NOT CH_MS AND ((CHV03_C >= ALM_CHV03_C_HH_SP) OR (ALM_CHV03_C_HH AND (CHV03_C > ALM_CHV03_C_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHV03_C_HH);
VLA_CHBPV_C_LL (Condition := NOT CH_MS AND ((CHBPV_C <= ALM_CHBPV_C_LL_SP) OR (ALM_CHBPV_C_LL AND (CHBPV_C < ALM_CHBPV_C_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHBPV_C_LL);
VLA_CHBPV_C_L (Condition := NOT CH_MS AND ((CHBPV_C <= ALM_CHBPV_C_L_SP) OR (ALM_CHBPV_C_L AND (CHBPV_C < ALM_CHBPV_C_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHBPV_C_L);
VLA_CHBPV_C_H (Condition := NOT CH_MS AND ((CHBPV_C >= ALM_CHBPV_C_H_SP) OR (ALM_CHBPV_C_H AND (CHBPV_C > ALM_CHBPV_C_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHBPV_C_H);
VLA_CHBPV_C_HH (Condition := NOT CH_MS AND ((CHBPV_C >= ALM_CHBPV_C_HH_SP) OR (ALM_CHBPV_C_HH AND (CHBPV_C > ALM_CHBPV_C_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHBPV_C_HH);
VLA_CHPVSD_FB_LL (Condition := NOT CH_MS AND ((CHPVSD_FB <= ALM_CHPVSD_FB_LL_SP) OR (ALM_CHPVSD_FB_LL AND (CHPVSD_FB < ALM_CHPVSD_FB_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHPVSD_FB_LL);
VLA_CHPVSD_FB_L (Condition := NOT CH_MS AND ((CHPVSD_FB <= ALM_CHPVSD_FB_L_SP) OR (ALM_CHPVSD_FB_L AND (CHPVSD_FB < ALM_CHPVSD_FB_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHPVSD_FB_L);
VLA_CHPVSD_FB_H (Condition := NOT CH_MS AND ((CHPVSD_FB >= ALM_CHPVSD_FB_H_SP) OR (ALM_CHPVSD_FB_H AND (CHPVSD_FB > ALM_CHPVSD_FB_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHPVSD_FB_H);
VLA_CHPVSD_FB_HH (Condition := NOT CH_MS AND ((CHPVSD_FB >= ALM_CHPVSD_FB_HH_SP) OR (ALM_CHPVSD_FB_HH AND (CHPVSD_FB > ALM_CHPVSD_FB_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHPVSD_FB_HH);
VLA_CHPVSD_C_LL (Condition := NOT CH_MS AND ((CHPVSD_C <= ALM_CHPVSD_C_LL_SP) OR (ALM_CHPVSD_C_LL AND (CHPVSD_C < ALM_CHPVSD_C_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHPVSD_C_LL);
VLA_CHPVSD_C_L (Condition := NOT CH_MS AND ((CHPVSD_C <= ALM_CHPVSD_C_L_SP) OR (ALM_CHPVSD_C_L AND (CHPVSD_C < ALM_CHPVSD_C_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHPVSD_C_L);
VLA_CHPVSD_C_H (Condition := NOT CH_MS AND ((CHPVSD_C >= ALM_CHPVSD_C_H_SP) OR (ALM_CHPVSD_C_H AND (CHPVSD_C > ALM_CHPVSD_C_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHPVSD_C_H);
VLA_CHPVSD_C_HH (Condition := NOT CH_MS AND ((CHPVSD_C >= ALM_CHPVSD_C_HH_SP) OR (ALM_CHPVSD_C_HH AND (CHPVSD_C > ALM_CHPVSD_C_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_CHPVSD_C_HH);
VLA_TST_CAP_LL (Condition := NOT CH_MS AND ((TST_CAP <= ALM_TST_CAP_LL_SP) OR (ALM_TST_CAP_LL AND (TST_CAP < ALM_TST_CAP_LL_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_TST_CAP_LL);
VLA_TST_CAP_L (Condition := NOT CH_MS AND ((TST_CAP <= ALM_TST_CAP_L_SP) OR (ALM_TST_CAP_L AND (TST_CAP < ALM_TST_CAP_L_SP + VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_TST_CAP_L);
VLA_TST_CAP_H (Condition := NOT CH_MS AND ((TST_CAP >= ALM_TST_CAP_H_SP) OR (ALM_TST_CAP_H AND (TST_CAP > ALM_TST_CAP_H_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_TST_CAP_H);
VLA_TST_CAP_HH (Condition := NOT CH_MS AND ((TST_CAP >= ALM_TST_CAP_HH_SP) OR (ALM_TST_CAP_HH AND (TST_CAP > ALM_TST_CAP_HH_SP - VLV_ALM_HYST))), SP_Condition_Delay := VLV_ALM_DLY, SEC_P := SEC_P, Condition_OK => ALM_TST_CAP_HH);
(* AI LL / L / H / HH alarms (FB_AnalogInput_Alarm): enabled except in maintenance (2026-10-20) *)
ALM_CHS_FL01_Alarm_Eanble := NOT CH_MS;
ALM_CHR_FL01_Alarm_Eanble := NOT CH_MS;
ALM_CHS_T01_Alarm_Eanble := NOT CH_MS;
ALM_CHS_T02_Alarm_Eanble := NOT CH_MS;
ALM_CHS_P01_Alarm_Eanble := NOT CH_MS;
ALM_CHR_P02_Alarm_Eanble := NOT CH_MS;
ALM_CHR_YP01_Alarm_Eanble := NOT CH_MS;
ALM_CHR_YP02_Alarm_Eanble := NOT CH_MS;
ALM_CHR_T01_Alarm_Eanble := NOT CH_MS;
ALM_CHIN_T01_Alarm_Eanble := NOT CH_MS;
ALM_PHTS_T01_Alarm_Eanble := NOT CH_MS;
ALM_PHTS_T02_Alarm_Eanble := NOT CH_MS;
ALM_PHTS_T03_Alarm_Eanble := NOT CH_MS;
ALM_PHTS_T04_Alarm_Eanble := NOT CH_MS;

ALM_UNIT_ANY := ALM_UNIT_ANY OR P06_SeqFault OR P06_StopFault OR P06_ConfigFault;

(* Pack status block %MW700..729, NOE IO Scanning writes it to SMCL %MW400.. *)
IF SEC_P THEN
    TX_HB := TX_HB + 1;
    IF TX_HB > 30000 THEN TX_HB := 0; END_IF;
END_IF;
TX_BITS1 := 0;
IF ACH_RUN THEN TX_BITS1 := TX_BITS1 OR 16#0001; END_IF;
IF CHP_RUN THEN TX_BITS1 := TX_BITS1 OR 16#0002; END_IF;
IF UNIT_ENABLE THEN TX_BITS1 := TX_BITS1 OR 16#0004; END_IF;
IF ACH_Fault THEN TX_BITS1 := TX_BITS1 OR 16#0008; END_IF;
IF CHWP_Fault THEN TX_BITS1 := TX_BITS1 OR 16#0010; END_IF;
IF CH_MS THEN TX_BITS1 := TX_BITS1 OR 16#0020; END_IF;
IF ACH_PWR THEN TX_BITS1 := TX_BITS1 OR 16#0040; END_IF;
IF ACH_AM THEN TX_BITS1 := TX_BITS1 OR 16#0080; END_IF;
IF CHP_REM THEN TX_BITS1 := TX_BITS1 OR 16#0100; END_IF;
IF Chiller_Start_ENA[4] THEN TX_BITS1 := TX_BITS1 OR 16#0200; END_IF;
IF Chiller_Stop_ENA[5] THEN TX_BITS1 := TX_BITS1 OR 16#0400; END_IF;
IF FPM_ENA[0] THEN TX_BITS1 := TX_BITS1 OR 16#0800; END_IF;
IF Chemical_Mode_ENA[0] THEN TX_BITS1 := TX_BITS1 OR 16#1000; END_IF;
IF TST_MS THEN TX_BITS1 := TX_BITS1 OR 16#2000; END_IF;
IF DISCH_ALM THEN TX_BITS1 := TX_BITS1 OR 16#4000; END_IF;
TX_BITS2 := 0;
IF ALM_CHBPV_MM THEN TX_BITS2 := TX_BITS2 OR 16#0001; END_IF;
IF ALM_CHV01_MM THEN TX_BITS2 := TX_BITS2 OR 16#0002; END_IF;
IF ALM_CHV02_MM THEN TX_BITS2 := TX_BITS2 OR 16#0004; END_IF;
IF ALM_CHV03_MM THEN TX_BITS2 := TX_BITS2 OR 16#0008; END_IF;
IF ALM_CHP_MM THEN TX_BITS2 := TX_BITS2 OR 16#0010; END_IF;
IF ALM_ACH_MM THEN TX_BITS2 := TX_BITS2 OR 16#0020; END_IF;
IF ACH_F1 THEN TX_BITS2 := TX_BITS2 OR 16#0040; END_IF;
IF ACHF_F THEN TX_BITS2 := TX_BITS2 OR 16#0080; END_IF;
IF CHP_FLT_DI OR VFD_ALM THEN TX_BITS2 := TX_BITS2 OR 16#0100; END_IF;
IF COMM_ACH_FAIL THEN TX_BITS2 := TX_BITS2 OR 16#0200; END_IF;
IF COMM_VFD_FAIL THEN TX_BITS2 := TX_BITS2 OR 16#0400; END_IF;
IF COMM_TST_FAIL THEN TX_BITS2 := TX_BITS2 OR 16#0800; END_IF;
IF PHTS_FLT THEN TX_BITS2 := TX_BITS2 OR 16#1000; END_IF;
IF ALM_FPM_LOWFL THEN TX_BITS2 := TX_BITS2 OR 16#2000; END_IF;
IF TST_NOCAP THEN TX_BITS2 := TX_BITS2 OR 16#4000; END_IF;
TX_TSTMODE := TST_MODE;
TX_RUNH_HI := DINT_TO_INT(CH_RUNH / 10000);
TX_RUNH_LO := DINT_TO_INT(CH_RUNH MOD 10000);
TX_ACHH_HI := DINT_TO_INT(ACH_RUNH / 10000);
TX_ACHH_LO := DINT_TO_INT(ACH_RUNH MOD 10000);
TX_TSTCAP := REAL_TO_INT(TST_CAP * 100.0);
TX_CHST01 := REAL_TO_INT(CHS_T01 * 100.0);
TX_CHST02 := REAL_TO_INT(CHS_T02 * 100.0);
TX_CHSFL01 := REAL_TO_INT(CHS_FL01 * 10.0);
TX_CHSFL02 := 0;      (* no CHS-FL02 in the I/O list, reserved *)
TX_CHRFL01 := REAL_TO_INT(CHR_FL01 * 10.0);
TX_CHINT01 := REAL_TO_INT(CHIN_T01 * 100.0);
TX_CHRT01 := REAL_TO_INT(CHR_T01 * 100.0);
TX_VSDFB := REAL_TO_INT(CHPVSD_FB * 100.0);
TX_CHV01FB := REAL_TO_INT(CHV01_FB * 100.0);
TX_CHV02FB := REAL_TO_INT(CHV02_FB * 100.0);
TX_CHV03FB := REAL_TO_INT(CHV03_FB * 100.0);
TX_CHBPVFB := REAL_TO_INT(CHBPV_FB * 100.0);
TX_TSPECHO := REAL_TO_INT(CHS_TSP_OUT * 100.0);
TX_SPDECHO := REAL_TO_INT(CHPVSD_C * 100.0);
(* 2026-10-19: b0 = enable command held by this unit (ACH_EN); the SMCL takes the stage back from it after a restart *)
TX_ENAFB := 0;
IF ACH_EN THEN TX_ENAFB := 1; END_IF;

(* Line 2 write area is allocated by the NOE row by row as %MW730..759; copy the same status block *)
TX2_BLK[0] := TX_HB;
TX2_BLK[1] := TX_BITS1;
TX2_BLK[2] := TX_BITS2;
TX2_BLK[3] := TX_TSTMODE;
TX2_BLK[4] := TX_RUNH_HI;
TX2_BLK[5] := TX_RUNH_LO;
TX2_BLK[6] := TX_ACHH_HI;
TX2_BLK[7] := TX_ACHH_LO;
TX2_BLK[8] := TX_TSTCAP;
TX2_BLK[9] := TX_CHST01;
TX2_BLK[10] := TX_CHST02;
TX2_BLK[11] := TX_CHSFL01;
TX2_BLK[12] := TX_CHSFL02;
TX2_BLK[13] := TX_CHRFL01;
TX2_BLK[14] := TX_CHINT01;
TX2_BLK[15] := TX_CHRT01;
TX2_BLK[16] := TX_VSDFB;
TX2_BLK[17] := TX_CHV01FB;
TX2_BLK[18] := TX_CHV02FB;
TX2_BLK[19] := TX_CHV03FB;
TX2_BLK[20] := TX_CHBPVFB;
TX2_BLK[21] := TX_TSPECHO;
TX2_BLK[22] := TX_SPDECHO;
TX2_BLK[23] := TX_ENAFB;
FOR I := 24 TO 29 DO TX2_BLK[I] := 0; END_FOR;

(* P06 extension: same 30-word status block, previously reserved +24/+25. *)
P06_TX_VER := 2606;
P06_TX_EXT := 0;
IF P06_SeqFault THEN P06_TX_EXT := P06_TX_EXT OR 16#0001; END_IF;
IF UNIT_ENABLE AND NOT P06_SeqFault AND NOT P06_ConfigFault AND NOT TST_MS
    AND NOT LOCAL_EN AND P06_TempValid AND (P06_State = 0) AND P06_TOff.Q
    AND NOT ACH_RUN AND NOT CHP_RUN THEN
    P06_TX_EXT := P06_TX_EXT OR 16#0002;
END_IF;
IF (P06_State = 40) AND P06_TOn.Q THEN P06_TX_EXT := P06_TX_EXT OR 16#0004; END_IF;
IF P06_TempValid THEN P06_TX_EXT := P06_TX_EXT OR 16#0008; END_IF;
IF P06_StopFault THEN P06_TX_EXT := P06_TX_EXT OR 16#0010; END_IF;
IF CHE_DUE THEN P06_TX_EXT := P06_TX_EXT OR 16#0020; END_IF;
IF LOCAL_EN THEN P06_TX_EXT := P06_TX_EXT OR 16#0040; END_IF;
(* Report the selected VALID temperature twice, never a failed held channel. *)
IF NOT (CHS_T01_UnderRange OR CHS_T01_OverRange) THEN P06_QualTemp := CHS_T01; END_IF;
IF NOT (CHS_T02_UnderRange OR CHS_T02_OverRange) THEN
    IF CHS_T01_UnderRange OR CHS_T01_OverRange THEN P06_QualTemp := CHS_T02;
    ELSE P06_QualTemp := MAX(P06_QualTemp, CHS_T02);
    END_IF;
END_IF;
TX_CHST01 := REAL_TO_INT(P06_QualTemp * 100.0);
TX_CHST02 := TX_CHST01;
TX2_BLK[9] := TX_CHST01; TX2_BLK[10] := TX_CHST02;
TX2_BLK[24] := P06_TX_VER; TX2_BLK[25] := P06_TX_EXT;

(* ================= SCADA map area (AVEVA Plant SCADA, Modbus TCP read only) =================
   %MW900..%MW939  HMI_W  engineering value x scale (INT), scale in the SCADA tag list
   %M1000..%M1223   HMI_X  digital / alarm bits
   This section only writes HMI_* and takes no part in control. Generated by hmi_map.py, do not edit by hand. *)
IF %S6 AND NOT HMI_S6 THEN
    HMI_HB := HMI_HB + 1;
    IF HMI_HB > 30000 THEN HMI_HB := 0; END_IF;
END_IF;
HMI_S6 := %S6;

HMI_W[0] := HMI_HB;
HMI_W[1] := UNIT_NO;
HMI_W[2] := REAL_TO_INT(LIMIT(-32000.0, CHS_FL01 * 100.0, 32000.0));   (* CHS_FL01 ×100 *)
HMI_W[3] := REAL_TO_INT(LIMIT(-32000.0, CHR_FL01 * 100.0, 32000.0));   (* CHR_FL01 ×100 *)
HMI_W[4] := REAL_TO_INT(LIMIT(-32000.0, CHS_T01 * 100.0, 32000.0));   (* CHS_T01 ×100 *)
HMI_W[5] := REAL_TO_INT(LIMIT(-32000.0, CHS_T02 * 100.0, 32000.0));   (* CHS_T02 ×100 *)
HMI_W[6] := REAL_TO_INT(LIMIT(-32000.0, CHV01_FB * 100.0, 32000.0));   (* CHV01_FB ×100 *)
HMI_W[7] := REAL_TO_INT(LIMIT(-32000.0, CHV02_FB * 100.0, 32000.0));   (* CHV02_FB ×100 *)
HMI_W[8] := REAL_TO_INT(LIMIT(-32000.0, CHV03_FB * 100.0, 32000.0));   (* CHV03_FB ×100 *)
HMI_W[9] := REAL_TO_INT(LIMIT(-32000.0, CHS_P01 * 100.0, 32000.0));   (* CHS_P01 ×100 *)
HMI_W[10] := REAL_TO_INT(LIMIT(-32000.0, CHR_P02 * 100.0, 32000.0));   (* CHR_P02 ×100 *)
HMI_W[11] := REAL_TO_INT(LIMIT(-32000.0, CHR_YP01 * 100.0, 32000.0));   (* CHR_YP01 ×100 *)
HMI_W[12] := REAL_TO_INT(LIMIT(-32000.0, CHR_YP02 * 100.0, 32000.0));   (* CHR_YP02 ×100 *)
HMI_W[13] := REAL_TO_INT(LIMIT(-32000.0, CHR_T01 * 100.0, 32000.0));   (* CHR_T01 ×100 *)
HMI_W[14] := REAL_TO_INT(LIMIT(-32000.0, CHIN_T01 * 100.0, 32000.0));   (* CHIN_T01 ×100 *)
HMI_W[15] := REAL_TO_INT(LIMIT(-32000.0, CHBPV_FB * 100.0, 32000.0));   (* CHBPV_FB ×100 *)
HMI_W[16] := REAL_TO_INT(LIMIT(-32000.0, PHTS_T01 * 100.0, 32000.0));   (* PHTS_T01 ×100 *)
HMI_W[17] := REAL_TO_INT(LIMIT(-32000.0, PHTS_T02 * 100.0, 32000.0));   (* PHTS_T02 ×100 *)
HMI_W[18] := REAL_TO_INT(LIMIT(-32000.0, PHTS_T03 * 100.0, 32000.0));   (* PHTS_T03 ×100 *)
HMI_W[19] := REAL_TO_INT(LIMIT(-32000.0, PHTS_T04 * 100.0, 32000.0));   (* PHTS_T04 ×100 *)
HMI_W[20] := REAL_TO_INT(LIMIT(-32000.0, CHPVSD_FB * 100.0, 32000.0));   (* CHPVSD_FB ×100 *)
HMI_W[21] := REAL_TO_INT(LIMIT(-32000.0, CHPVSD_C * 100.0, 32000.0));   (* CHPVSD_C ×100 *)
HMI_W[22] := REAL_TO_INT(LIMIT(-32000.0, CHV01_C * 100.0, 32000.0));   (* CHV01_C ×100 *)
HMI_W[23] := REAL_TO_INT(LIMIT(-32000.0, CHV02_C * 100.0, 32000.0));   (* CHV02_C ×100 *)
HMI_W[24] := REAL_TO_INT(LIMIT(-32000.0, CHV03_C * 100.0, 32000.0));   (* CHV03_C ×100 *)
HMI_W[25] := REAL_TO_INT(LIMIT(-32000.0, CHBPV_C * 100.0, 32000.0));   (* CHBPV_C ×100 *)


(* ---- alarm memory over a cold start (2026-10-19) ----
   ALM_MEM (%MW1600.., kept with 'Initialize %MWi on cold start' off) = HMI_X of the last scan.
   First scan after a cold start (ALM_MEM_DONE = FALSE) with a matching layout signature ALM_SIG:
   the alarms active before the power loss stay active for ALM_HOLD_TM s, until the live alarm comes
   back by itself, or until an alarm reset; latched alarms go back into their latch variable. *)
IF NOT ALM_MEM_DONE THEN
    ALM_MEM_DONE := TRUE;
    ALM_HOLD := ALM_SIG = 14306;
    ALM_HOLD_CNT := 0;
    IF ALM_HOLD_TM <= 0 THEN ALM_HOLD_TM := 1200; END_IF;
    FOR HMI_K := 0 TO 223 DO
        ALM_OLD[HMI_K] := ALM_HOLD AND ((ALM_MEM[HMI_K / 16] AND SHL(16#0001, INT_TO_UINT(HMI_K MOD 16))) <> 0);
    END_FOR;
    IF ALM_HOLD THEN
        ALM_CHV01_MM := ALM_OLD[100];
        ALM_CHV02_MM := ALM_OLD[101];
        ALM_CHV03_MM := ALM_OLD[102];
        ALM_CHBPV_MM := ALM_OLD[103];
        ALM_CHP_MM := ALM_OLD[104];
        ALM_ACH_MM := ALM_OLD[105];
    END_IF;
END_IF;
IF ALM_HOLD AND SEC_P THEN ALM_HOLD_CNT := ALM_HOLD_CNT + 1; END_IF;
IF (ALM_HOLD_CNT >= ALM_HOLD_TM) OR (SMCL_RESET OR UNIT_Reset) THEN ALM_HOLD := FALSE; END_IF;

HMI_X[0] := CHWP_S;
IF CHWP_F THEN ALM_OLD[1] := FALSE; END_IF;  HMI_X[1] := CHWP_F OR (ALM_HOLD AND ALM_OLD[1]);
IF NOT CHWP_AM THEN ALM_OLD[2] := TRUE; END_IF;  HMI_X[2] := CHWP_AM AND (NOT ALM_HOLD OR ALM_OLD[2]);
HMI_X[3] := ACH_S;
IF ACH_F01 THEN ALM_OLD[4] := FALSE; END_IF;  HMI_X[4] := ACH_F01 OR (ALM_HOLD AND ALM_OLD[4]);
IF NOT ACH_PW THEN ALM_OLD[5] := TRUE; END_IF;  HMI_X[5] := ACH_PW AND (NOT ALM_HOLD OR ALM_OLD[5]);
HMI_X[6] := PHTS_S;
IF PHTS_F THEN ALM_OLD[7] := FALSE; END_IF;  HMI_X[7] := PHTS_F OR (ALM_HOLD AND ALM_OLD[7]);
IF %I0.6.8 THEN ALM_OLD[8] := FALSE; END_IF;  HMI_X[8] := %I0.6.8 OR (ALM_HOLD AND ALM_OLD[8]);
HMI_X[16] := CHP_STC;
HMI_X[17] := CHP_SPC;
HMI_X[18] := ACH_STC;
HMI_X[19] := ACH_SPC;
HMI_X[20] := PHTS_C;
IF SIM_EN THEN ALM_OLD[24] := FALSE; END_IF;  HMI_X[24] := SIM_EN OR (ALM_HOLD AND ALM_OLD[24]);
IF NOT SMCL_COMM_OK THEN ALM_OLD[25] := TRUE; END_IF;  HMI_X[25] := SMCL_COMM_OK AND (NOT ALM_HOLD OR ALM_OLD[25]);
